package handlers

import (
	"backend/models"
	"backend/storage"

	"github.com/gin-gonic/gin"
)

func CreateUser(c *gin.Context) {

	var user models.User

	err := c.BindJSON(&user)

	if err != nil {

		c.JSON(400, gin.H{
			"error": "invalid json",
		})

		return
	}

	storage.Users = append(storage.Users, user)

	c.JSON(201, user)
}

package handlers

import (
	"fmt"
	"backend/storage"
	"github.com/gin-gonic/gin"
)

func DeleteUser(c *gin.Context) {
	id := c.Param("id")

	// loop over the users 
	for index, user := range storage.Users {
		// if found the id .. delete the user and return 
		if fmt.Sprint(user.ID) == id {
			storage.Users = append(storage.Users[:index], storage.Users[index+1:]...)
		}
		c.JSON(200, gin.H{
			"messege" : "user successfully deleted",
		})
		return
	}

	c.JSON(400, gin.H{
		"error" : "user not found",
	})
}

package handlers

import (
	"backend/storage"
	"fmt"
	"github.com/gin-gonic/gin"
)

func GetUser(c *gin.Context) {
	id := c.Param("id")
	// loop over the users 
	for _, user := range storage.Users {
		// if id found show the user details 
		if fmt.Sprint(user.ID) == id {
			c.JSON(200, user)
		}
		return
	}

	// error - user not found 
	c.JSON(400, gin.H{
		"error" : "id not found",
	})
}

