package handlers

import (
	"github.com/gin-gonic/gin"
	"backend/storage"
	"fmt"
	"backend/models"
)

func UpdateUser(c *gin.Context) {
	// get the id of the user form the path params
	id := c.Param("id")

	// create a user tye variable
	var updateuser models.User

	// jsonify and error handling
	err := c.BindJSON(&updateuser)
	if err != nil {
		c.JSON(400, gin.H{
			"error" : "wrong json format",
		})
		return
	}

	// loop over the users
	for index, user := range storage.Users {
		// if the id found then update the user details and return
		if fmt.Sprint(user.ID) == id {
			storage.Users[index].Name = updateuser.Name
			storage.Users[index].Age = updateuser.Age
			c.JSON(200, storage.Users[index])

			return
		}
	}

	c.JSON(400, gin.H{
		"error" : "user not found",
	})
}

package main

import (
	"backend/routes"
	"os"

	"github.com/gin-contrib/cors"
	"github.com/gin-gonic/gin"
)

func main() {

	r := gin.Default()

	r.Use(cors.New(cors.Config{
		AllowOrigins: []string{
			"https://crudgo.vercel.app",
		},

		AllowMethods: []string{
			"GET",
			"POST",
			"PUT",
			"DELETE",
			"OPTIONS",
		},

		AllowHeaders: []string{
			"Origin",
			"Content-Type",
		},
	}))

	routes.UserRoutes(r)

	port := os.Getenv("PORT")

	if port == "" {
		port = "8080"
	}

	r.Run(":" + port)
}

package models

// models / schema
type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
	Age  int    `json:"age"`
}

package routes

import (
	"backend/handlers"
	"github.com/gin-gonic/gin"
)

func UserRoutes(r *gin.Engine) {
	r.GET("/users", handlers.GetUsers)
	r.POST("/users", handlers.CreateUser)
	r.GET("/users/:id", handlers.GetUser)
	r.DELETE("/users/:id", handlers.DeleteUser)
	r.PUT("/users/:id", handlers.UpdateUser)
}

const API_URL = "https://crud-go-4nut.onrender.com/users"

function showMessage(text, color) {

  const message = document.getElementById("message")

  message.innerText = text

  message.style.color = color
}

async function getUsers() {

  const response = await fetch(API_URL)

  const users = await response.json()

  const container = document.getElementById("users-container")

  container.innerHTML = ""

  users.forEach(user => {

    container.innerHTML += `
      <div class="user-card">

        <h2>${user.name}</h2>

        <p><strong>ID:</strong> ${user.id}</p>

        <p><strong>Age:</strong> ${user.age}</p>

        <div class="card-buttons">

          <button 
            class="edit-btn"
            onclick="fillForm(${user.id}, '${user.name}', ${user.age})"
          >
            Edit
          </button>

          <button
            class="delete-btn"
            onclick="deleteUser(${user.id})"
          >
            Delete
          </button>

        </div>

      </div>
    `
  })
}

async function addUser() {

  const id = Number(document.getElementById("id").value)

  const name = document.getElementById("name").value

  const age = Number(document.getElementById("age").value)

  const user = {
    id,
    name,
    age
  }

  const response = await fetch(API_URL, {
    method: "POST",

    headers: {
      "Content-Type": "application/json"
    },

    body: JSON.stringify(user)
  })

  const data = await response.json()

  if (!response.ok) {

    showMessage(data.error, "red")

    return
  }

  showMessage("User added successfully", "lightgreen")

  clearForm()

  getUsers()
}

async function deleteUser(id) {

  const response = await fetch(`${API_URL}/${id}`, {
    method: "DELETE"
  })

  const data = await response.json()

  if (!response.ok) {

    showMessage(data.error, "red")

    return
  }

  showMessage(data.message, "lightgreen")

  getUsers()
}

function fillForm(id, name, age) {

  document.getElementById("id").value = id

  document.getElementById("name").value = name

  document.getElementById("age").value = age
}

async function updateUser() {

  const id = document.getElementById("id").value

  const updatedUser = {
    name: document.getElementById("name").value,

    age: Number(document.getElementById("age").value)
  }

  const response = await fetch(`${API_URL}/${id}`, {
    method: "PUT",

    headers: {
      "Content-Type": "application/json"
    },

    body: JSON.stringify(updatedUser)
  })

  const data = await response.json()

  if (!response.ok) {

    showMessage(data.error, "red")

    return
  }

  showMessage("User updated successfully", "lightgreen")

  clearForm()

  getUsers()
}

function clearForm() {

  document.getElementById("id").value = ""

  document.getElementById("name").value = ""

  document.getElementById("age").value = ""
}

getUsers()

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: Arial, sans-serif;
  background: #0f172a;
  color: white;
  padding: 20px;
}

.container {
  max-width: 900px;
  margin: auto;
}

h1 {
  text-align: center;
  margin-bottom: 30px;
}

.form-container {
  background: #1e293b;
  padding: 20px;
  border-radius: 12px;

  display: flex;
  flex-direction: column;
  gap: 15px;

  margin-bottom: 30px;
}

input {
  padding: 14px;
  border: none;
  border-radius: 8px;
  outline: none;
  font-size: 16px;
}

.button-group {
  display: flex;
  gap: 10px;
}

button {
  flex: 1;
  padding: 14px;
  border: none;
  border-radius: 8px;

  background: #2563eb;
  color: white;

  font-size: 16px;

  cursor: pointer;

  transition: 0.2s;
}

button:hover {
  background: #1d4ed8;
}

#message {
  text-align: center;
  font-weight: bold;
  margin-top: 5px;
}

#users-container {
  display: grid;
  gap: 20px;
}

.user-card {
  background: #1e293b;
  padding: 20px;
  border-radius: 12px;
}

.user-card h2 {
  margin-bottom: 12px;
}

.user-card p {
  margin-bottom: 8px;
}

.card-buttons {
  margin-top: 15px;

  display: flex;
  gap: 10px;
}

.edit-btn {
  background: #059669;
}

.edit-btn:hover {
  background: #047857;
}

.delete-btn {
  background: #dc2626;
}

.delete-btn:hover {
  background: #b91c1c;
}

@media (max-width: 600px) {

  .button-group {
    flex-direction: column;
  }

  .card-buttons {
    flex-direction: column;
  }
}
